def _runtime_lifecycle_build_span(text: str) -> tuple[int, int]:
    text = _reviewed_configure_projection(text)
    masked = _code_mask(text)
    starts = list(re.finditer(r"\bconst\s+runtime_lifecycle_target\s*=", masked))
    branches = list(re.finditer(r"\bif\s*\(\s*runtime_lifecycle_native_supported\s*\)\s*\{", masked))
    aggregate = list(re.finditer(
        r"\bif\s*\(\s*runtime_lifecycle_native_supported\s*\)\s*"
        r"test_step\s*\.\s*dependOn\s*\(\s*test_runtime_lifecycle_step\s*\)\s*;", masked))
    if len(starts) != 1 or len(branches) != 1 or len(aggregate) != 1:
        raise InventoryError("runtime lifecycle block or aggregate boundary changed")
    start = starts[0].start()
    open_brace = masked.find("{", branches[0].start(), branches[0].end())
    close_brace = _matching_brace(masked, open_brace)
    otherwise = re.match(r"\s*else\s*\{", masked[close_brace + 1:])
    if otherwise is None:
        raise InventoryError("runtime lifecycle unsupported branch missing")
    end = _matching_brace(masked, close_brace + 1 + otherwise.end() - 1) + 1
    block = text[start:end]
    if hashlib.sha256(_compact_zig_contract(block).encode()).hexdigest() != RUNTIME_LIFECYCLE_BUILD_CONTRACT_SHA256:
        raise InventoryError("runtime lifecycle material build contract drifted")
    for position in (start, aggregate[0].start()):
        outer = [_compact_zig_contract(fragment) for fragment in _enclosing_control_context(text, position)
                 if _code_mask(fragment).strip()]
        if outer != [_compact_zig_contract("pub fn build(b: *std.Build) void {")]:
            raise InventoryError("runtime lifecycle outer applicability changed")
    owned = set(re.findall(r"\b(?:const|var)\s+([A-Za-z_][A-Za-z0-9_]*)(?:\s*:[^=;\n]+)?\s*=", _code_mask(block)))
    outside = masked[:start] + " " * (end - start) + masked[end:]
    edge = aggregate[0]
    outside = outside[:edge.start()] + " " * (edge.end() - edge.start()) + outside[edge.end():]
    for name in owned:
        if re.search(rf"\b{re.escape(name)}\b", outside):
            raise InventoryError("runtime lifecycle binding escapes reviewed block: " + name)
    return start, end


def _runtime_lifecycle_python_tree_contract(tree: ast.Module) -> None:
    # This also binds CASES, imports, main guard and all module-level rebinding.
    if _json_fact_digest(_canonical_python_ast(tree)) != RUNTIME_LIFECYCLE_PYTHON_AST_SHA256:
        raise InventoryError("runtime lifecycle complete controller AST changed")


def _runtime_lifecycle_source_contract(active: DiscoveryContext) -> None:
    for path, expected in RUNTIME_LIFECYCLE_SOURCE_SHA256.items():
        source = _frozen_regular_bytes(active, path, "runtime lifecycle source closure")
        if hashlib.sha256(source).hexdigest() != expected:
            raise InventoryError("runtime lifecycle support contract changed: " + path)


def _annotate_runtime_lifecycle_build(text: str, observations: list[dict[str, Any]]) -> None:
    _runtime_lifecycle_build_span(text)
    for identifier, template in RUNTIME_LIFECYCLE_OBSERVATION_TEMPLATES.items():
        matches = [row for row in observations if row["id"] == identifier]
        if len(matches) != 1:
            raise InventoryError("runtime lifecycle graph identity changed: " + identifier)
        matches[0].update(copy.deepcopy(template))


def _validate_runtime_lifecycle_contract(inventory: dict[str, Any], errors: list[str]) -> None:
    for section, templates in (
        ("build_observations", RUNTIME_LIFECYCLE_OBSERVATION_TEMPLATES),
        ("python_launches", {RUNTIME_LIFECYCLE_PYTHON_LAUNCH_ID: RUNTIME_LIFECYCLE_PYTHON_TEMPLATE}),
    ):
        for identifier, template in templates.items():
            matches = [row for row in inventory[section] if row.get("id") == identifier]
            _require(len(matches) == 1, "runtime lifecycle exact identity missing/duplicated: " + identifier, errors)
            if len(matches) != 1:
                continue
            for field, expected in template.items():
                _require(matches[0].get(field) == expected,
                         f"{identifier}: runtime lifecycle {field} changed", errors)
    python_rows = [row for row in inventory["python_launches"]
                   if row.get("anchor", {}).get("file") == "test/runtime/run_blas_io_lifecycle.py"]
    _require([row["id"] for row in python_rows] == [RUNTIME_LIFECYCLE_PYTHON_LAUNCH_ID],
             "runtime lifecycle controller must have exactly one subprocess launch", errors)
    aggregate = next((row for row in inventory["build_observations"]
                      if row.get("id") == TEST_INVENTORY_AGGREGATE_STEP_ID), {})
    _require([edge for edge in aggregate.get("direct_dependencies", [])
              if edge.get("id") == RUNTIME_LIFECYCLE_STEP_ID]
             == [{"id": RUNTIME_LIFECYCLE_STEP_ID, "condition": RUNTIME_LIFECYCLE_CONDITION}],
             "runtime lifecycle canonical aggregate applicability changed", errors)


def _checked_abi_build_span(text: str) -> tuple[int, int]:
    masked = _code_mask(text)
    starts = list(re.finditer(r"\bconst\s+install_checked_abi\s*=", masked))
    ends = list(_calls(text, "test_checked_fortran_step.dependOn"))
    if len(starts) != 1 or len(ends) != 2:
        raise InventoryError("checked ABI block boundaries changed")
    start = starts[0].start()
    end = ends[-1][0] + len(ends[-1][1])
    if masked[end:].lstrip()[:1] != ";":
        raise InventoryError("checked ABI block terminator changed")
    end = masked.find(";", end) + 1
    block = text[start:end]
    if hashlib.sha256(_compact_zig_contract(block).encode()).hexdigest() != CHECKED_ABI_BUILD_CONTRACT_SHA256:
        raise InventoryError("checked ABI material build contract drifted")
    owned = set(re.findall(r"\b(?:const|var)\s+([A-Za-z_][A-Za-z0-9_]*)(?:\s*:[^=;\n]+)?\s*=", _code_mask(block)))
    outside = masked[:start] + masked[end:]
    for name in owned:
        if re.search(rf"\b{re.escape(name)}\b", outside):
            raise InventoryError("checked ABI binding escapes reviewed block: " + name)
    return start, end


def _checked_abi_receiver_uses(text: str) -> set[tuple[int, int]]:
    start, end = _checked_abi_build_span(text)
    calls = list(_calls(text, "std.Build.Step.Run.create"))
    if len(calls) != 1 or not start <= calls[0][0] < end:
        raise InventoryError("checked ABI Fortran Run.create must have exactly one reviewed occurrence")
    position, call = calls[0]
    if _compact_zig_contract(call) != 'std.Build.Step.Run.create(b,"run checked Fortran consumer")':
        raise InventoryError("checked ABI Run.create receiver contract changed")
    match = re.search(r"\(\s*(b)\s*,", _code_mask(call))
    assert match is not None
    return {(position + match.start(1), position + match.end(1))}


def _checked_abi_source_contract(active: DiscoveryContext) -> None:
    for path, expected in CHECKED_ABI_SOURCE_SHA256.items():
        source = _frozen_regular_bytes(active, path, "checked ABI source closure")
        if hashlib.sha256(source).hexdigest() != expected:
            raise InventoryError("checked ABI source/ownership/schema contract changed: " + path)


def _annotate_checked_abi_build(text: str, observations: list[dict[str, Any]]) -> None:
    start, end = _checked_abi_build_span(text)
    calls = list(_calls(text, "std.Build.Step.Run.create"))
    if len(calls) != 1:
        raise InventoryError("checked ABI Run.create occurrence changed")
    position, call = calls[0]
    observations.append({
        "id": "launch:build.zig:build:run_checked_fortran_smoke",
        "category": "launch", "call": "std.Build.Step.Run.create",
        "anchor": {"file": "build.zig", "enclosing_function": "build", "symbol": "run_checked_fortran_smoke", "ordinal": 1},
        "source_digest": _semantic_digest([_compact_zig_contract(text[start:end])]),
        "checked_abi_contract_sha256": CHECKED_ABI_BUILD_CONTRACT_SHA256,
        "native_inventory_evidence": False,
    })
    checked_ids = {row["id"] for row in observations if row.get("checked_abi_contract_sha256") == CHECKED_ABI_BUILD_CONTRACT_SHA256}
    shared_install_ids = {
        "install:build.zig:build:include/zynum/checked/checked.h",
        "install:build.zig:build:include/zynum/checked/checked.f90",
        "install:build.zig:build:include/zynum/checked/abi_manifest.json",
    }
    expected_checked_ids = set(CHECKED_ABI_OBSERVATION_TEMPLATES) - shared_install_ids
    if checked_ids != expected_checked_ids:
        raise InventoryError("checked ABI graph projection changed: " + repr(sorted(checked_ids ^ expected_checked_ids)))


# This is one reviewed build-composition seam, not a general function resolver.
