def _reviewed_configure_projection(text: str) -> str:
    if re.search(r"\bpub\s+const\s+ExecutionProfile\s*=", _code_mask(text)):
        return _reviewed_native_configure_projection(text)
    return _legacy_reviewed_configure_projection(text)


def _reviewed_native_configure_projection(text: str) -> str:
    """Validate both mutually exclusive graphs, then expose the reference body.

    Original offsets/newlines remain intact. Integrated helpers are bound in
    full, never treated as unreviewed hidden code or executed native evidence.
    The legacy graph extractor still checks every original reference edge.
    """
    masked = _code_mask(text)
    def fail(reason: str) -> None:
        raise InventoryError("reviewed native configure seam changed: " + reason)
    def function(name: str) -> tuple[int, int, int]:
        matches = list(re.finditer(r"\b(?:pub\s+)?fn\s+" + re.escape(name) + r"\s*\(", masked))
        if len(matches) != 1:
            fail("function declaration count: " + name)
        start = matches[0].start()
        opening = masked.find("{", matches[0].end())
        if opening < 0 or _zig_brace_depth(masked, 0, start) != 0:
            fail("helper must be top-level: " + name)
        return start, opening, _matching_brace(masked, opening)
    def statement(pattern: str) -> tuple[int, int]:
        matches = list(re.finditer(pattern, masked))
        if len(matches) != 1:
            fail("declaration: " + pattern)
        start = matches[0].start()
        return start, _zig_statement_end(masked, matches[0].end(), len(masked)) + 1
    build = function("build")
    configure = function("configure")
    if _compact_zig_contract(text[build[0]:build[1] + 1]) != "pubfnbuild(b:*std.Build)void{":
        fail("thin build signature")
    if _compact_zig_contract(text[build[1] + 1:build[2]]) != "_=configure(b);":
        fail("build must call configure exactly once without forwarding or guards")
    if len(re.findall(r"\bconfigure\b", masked)) != 2 or len(re.findall(r"\bbuild\b", masked)) != 1:
        fail("extra configure/build reference")
    if _compact_zig_contract(text[configure[0]:configure[1] + 1]) != "pubfnconfigure(b:*std.Build)ImplementationGraph{":
        fail("configure signature")
    helper_spans = {}
    for name, digest in INJECTION_HELPER_CONTRACT_SHA256.items():
        current = function(name)
        helper_spans[name] = current
        if hashlib.sha256(_compact_zig_contract(text[current[0]:current[2] + 1]).encode()).hexdigest() != digest:
            fail("reviewed helper body/identity: " + name)
    profile = statement(r"\bpub\s+const\s+ExecutionProfile\s*=")
    if _compact_zig_contract(text[profile[0]:profile[1]]) != "pubconstExecutionProfile=enum{reference,integrated_native};":
        fail("profile alternatives")
    graph = statement(r"\bpub\s+const\s+ImplementationGraph\s*=")
    expected_graph = ("pubconstImplementationGraph=struct{core:*std.Build.Module,execution:*std.Build.Module,"
        "resources:*std.Build.Module,options:*std.Build.Module,provider_c:*std.Build.Module,native:*std.Build.Module,"
        "main_library:?*std.Build.Step.Compile=null,lapacke_binding:?*std.Build.Module=null,mkl_sparse_binding:?*std.Build.Module=null,};")
    if _compact_zig_contract(text[graph[0]:graph[1]]) != expected_graph:
        fail("exact profile graph fields/defaults")
    boundaries = list(re.finditer(r"\bconst\s+blas_interface\s*=", masked[configure[1] + 1:configure[2]]))
    if len(boundaries) != 1:
        fail("reference branch boundary")
    prefix_end = configure[1] + 1 + boundaries[0].start()
    prefix = text[configure[1] + 1:prefix_end]
    if hashlib.sha256(_compact_zig_contract(prefix).encode()).hexdigest() != INJECTION_PROFILE_PREFIX_SHA256:
        fail("profile exclusivity/default owner/SDK dispatch prefix")
    # The reviewed prefix rejects contradictory legacy options and exits into
    # the integrated graph before any reference owner is constructed.
    if _compact_zig_contract(prefix).count("if(execution_profile==.integrated_native)returnconfigureIntegrated(b,heteris_include);") != 1:
        fail("integrated branch must return before reference assembly")
    returns = list(re.finditer(r"\breturn\b", masked[prefix_end:configure[2]]))
    if len(returns) != 1:
        fail("reference final return count")
    return_start = prefix_end + returns[0].start()
    expected_return = "return.{.provider_c=provider_c,.native=native," + "".join(
        "." + field + "=" + owner + "," for field, owner in CONFIGURE_MODULE_RETURNS) + "};"
    if _compact_zig_contract(text[return_start:configure[2]]) != expected_return:
        fail("reference final return must contain the exact original owners and native aliases")
    trailer_matches = list(re.finditer(r"\bconst\s+native\s*=\s*addNativeFacade\s*\(", masked[prefix_end:return_start]))
    if len(trailer_matches) != 1:
        fail("reference native facade owner")
    trailer_start = prefix_end + trailer_matches[0].start()
    if hashlib.sha256(_compact_zig_contract(text[trailer_start:return_start]).encode()).hexdigest() != INJECTION_REFERENCE_TRAILER_SHA256:
        fail("reference alias/module publication trailer")
    graph_allowed = [graph, (configure[0], configure[1]),
        (helper_spans["configureIntegrated"][0], helper_spans["configureIntegrated"][2] + 1),
        (helper_spans["addPlatformLibrary"][0], helper_spans["addPlatformLibrary"][2] + 1)]
    for occurrence in re.finditer(r"\bImplementationGraph\b", masked):
        if not any(start <= occurrence.start() < end for start, end in graph_allowed):
            fail("graph type escapes the finite composition")
    allowed_helpers = [(start, closing + 1) for start, _, closing in helper_spans.values()] + [
        (configure[1] + 1, prefix_end), (trailer_start, return_start)]
    for name in INJECTION_HELPER_CONTRACT_SHA256:
        # Provider translation also has two reviewed reference-only call sites,
        # bound by the complete reference graph and lifecycle contracts.
        if name == "translateProvider":
            continue
        for occurrence in re.finditer(r"\b" + re.escape(name) + r"\b", masked):
            if not any(start <= occurrence.start() < end for start, end in allowed_helpers):
                fail("helper reference escapes composition: " + name)
    projected = list(text)
    def blank(start: int, end: int) -> None:
        for index in range(start, end):
            if text[index] != "\n": projected[index] = " "
    for start, end in [profile, (configure[1] + 1, prefix_end), (trailer_start, return_start),
                       *[(start, closing + 1) for start, _, closing in helper_spans.values()]]:
        blank(start, end)
    # Present only the actual non-null reference owners to the old finite seam.
    for name in ("provider_c", "native", "main_library"):
        match = re.search(r"\b" + name + r"\s*:", masked[graph[0]:graph[1]])
        if match is None: fail("graph field: " + name)
        start = graph[0] + match.start()
        end = text.find(",", start, graph[1]) + 1
        blank(start, end)
    for name in ("lapacke_binding", "mkl_sparse_binding"):
        match = re.search(r"\b" + name + r"\s*:\s*\?", masked[graph[0]:graph[1]])
        if match is None: fail("nullable reference field: " + name)
        position = graph[0] + match.end() - 1
        blank(position, position + 1)
        assignment = text.index("=", position, graph[1])
        blank(assignment, text.index(",", assignment, graph[1]))
    for name in ("provider_c", "native"):
        match = re.search(r"\." + name + r"\s*=", masked[return_start:configure[2]])
        if match is None: fail("reference return: " + name)
        start = return_start + match.start()
        blank(start, text.index(",", start, configure[2]) + 1)
    return _legacy_reviewed_configure_projection("".join(projected))


def _legacy_reviewed_configure_projection(text: str) -> str:
    """Validate the entire finite seam before projecting its existing build body.

    Offsets and newlines are retained, including every original body statement.
    Only the checked wrapper/type/return are blanked; the six actual owners are
    still validated by the existing complete resource/module graph contract.
    Discovery hashes the unprojected source separately in _call_semantics.
    """
    masked = _code_mask(text)
    if not re.search(r"\b(?:configure|ImplementationGraph)\b", masked):
        return text

    def fail(reason: str) -> None:
        raise InventoryError("reviewed configure seam changed: " + reason)

    functions = {}
    for name, result in (("build", "void"), ("configure", "ImplementationGraph")):
        declarations = list(re.finditer(r"\b(?:pub\s+)?fn\s+" + name + r"\s*\(", masked))
        if len(declarations) != 1:
            fail(name + " declaration count")
        start = declarations[0].start()
        opening = masked.find("{", declarations[0].end())
        statement_start = _top_level_statement_start(masked, 0, start)
        if (opening < 0 or _zig_brace_depth(masked, 0, start) != 0
                or masked[statement_start:start].strip()):
            fail(name + " must be top-level with no extra qualifiers")
        if _compact_zig_contract(text[start:opening + 1]) != "pubfn" + name + "(b:*std.Build)" + result + "{":
            fail(name + " signature")
        closing = _matching_brace(masked, opening)
        functions[name] = (start, opening, closing)
    build_start, build_open, build_close = functions["build"]
    config_start, config_open, config_close = functions["configure"]
    if _compact_zig_contract(text[build_open + 1:build_close]) != "_=configure(b);":
        fail("build must call configure exactly once without forwarding or guards")
    # These exact occurrences exclude calls, recursion, aliases and escaped
    # references anywhere else, including declarations outside the two bodies.
    if len(re.findall(r"\bconfigure\b", masked)) != 2 or len(re.findall(r"\bbuild\b", masked)) != 1:
        fail("extra configure/build reference")
    if len(re.findall(r"\bImplementationGraph\b", masked)) != 2:
        fail("graph type reference count")
    declarations = list(re.finditer(r"\bpub\s+const\s+ImplementationGraph\s*=", masked))
    if len(declarations) != 1:
        fail("graph declaration")
    graph_start = declarations[0].start()
    graph_end = _zig_statement_end(masked, declarations[0].end(), len(masked)) + 1
    expected_graph = "pubconstImplementationGraph=struct{" + "".join(
        field + ":*std.Build.Module," for field, _ in CONFIGURE_MODULE_RETURNS
    ) + "};"
    if (_zig_brace_depth(masked, 0, graph_start) != 0
            or _compact_zig_contract(text[graph_start:graph_end]) != expected_graph
            or masked[_top_level_statement_start(masked, 0, graph_start):graph_start].strip()
            or not graph_end <= build_start < build_close < config_start
            or _compact_zig_contract(text[graph_end:build_start])
            or _compact_zig_contract(text[build_close + 1:config_start])):
        fail("exact graph fields or top-level declaration order")
    returns = list(re.finditer(r"\breturn\b", masked[config_open + 1:config_close]))
    if len(returns) != 1:
        fail("configure requires one unconditional final return")
    return_start = config_open + 1 + returns[0].start()
    if _zig_brace_depth(masked, config_open, return_start) != 1:
        fail("conditional or nested return")
    expected_return = "return.{" + "".join(
        "." + field + "=" + owner + "," for field, owner in CONFIGURE_MODULE_RETURNS
    ) + "};"
    if _compact_zig_contract(text[return_start:config_close]) != expected_return:
        fail("final return must contain only the six production locals")
    for _, owner in CONFIGURE_MODULE_RETURNS:
        owners = list(re.finditer(r"\b(?:const|var)\s+" + owner + r"\b", masked))
        if (len(owners) != 1 or not config_open < owners[0].start() < return_start
                or _zig_brace_depth(masked, config_open, owners[0].start()) != 1
                or not re.match(r"const\s+" + owner + r"\s*=", masked[owners[0].start():])):
            fail("missing, mutable or shadowed production owner: " + owner)

    projected = list(text)
    for start, end in ((graph_start, graph_end), (build_start, build_close + 1),
                       (return_start, config_close)):
        for index in range(start, end):
            if text[index] != "\n":
                projected[index] = " "
    # Replace only identifiers, never compact the surrounding source or lines.
    header = masked[config_start:config_open]
    for old, new in (("configure", "build"), ("ImplementationGraph", "void")):
        match = re.search(r"\b" + old + r"\b", header)
        assert match is not None
        start = config_start + match.start()
        projected[start:start + len(old)] = new + " " * (len(old) - len(new))
    return "".join(projected)




