def _fftw_f32_build_contract(text: str) -> dict[str, Any]:
    """Bind one optional scalar companion and its existing Module owners.

    The three LazyPath.path calls borrow the Build receiver only for paths in
    one cache-owned output directory. No generic receiver escape is admitted.
    """
    masked = _code_mask(text)
    declarations = list(re.finditer(r"\bconst\s+fft_f32\s*=", masked))
    if len(declarations) != 1:
        raise InventoryError("FFTW f32 selector declaration missing or duplicated")
    row, = declarations
    option_end = _zig_statement_end(masked, row.end(), len(masked)) + 1
    option = _compact_zig_contract(text[row.start():option_end])
    if re.fullmatch(r'constfft_f32=b\.option\(bool,"fft-f32","(?:\\.|[^"\\])*"\)orelsefalse;', option) is None:
        raise InventoryError("FFTW f32 selector default/type/name changed")
    guard = list(re.finditer(r"\bif\s*\(\s*fft_f32\s+and\s+fft_interface\s*!=\s*\.fftw3\s*\)\s*@panic\s*\(", masked))
    if len(guard) != 1 or guard[0].start() < option_end:
        raise InventoryError("FFTW f32 prerequisite guard missing or duplicated")
    guard_end = _matching_paren(text, masked.find("(", guard[0].start() + masked[guard[0].start():].index("@panic"))) + 1
    if _compact_zig_contract(text[guard[0].start():guard_end]) != 'if(fft_f32andfft_interface!=.fftw3)@panic("-Dfft-f32=true requires -Dfft-interface=fftw3")':
        raise InventoryError("FFTW f32 prerequisite guard changed")
    start_marker = "        var fftw_f32_manifest: ?std.Build.LazyPath = null;"
    end_marker = "        const abplas_lp64_static = b.addLibrary("
    if text.count(start_marker) != 1 or text.count(end_marker) != 1:
        raise InventoryError("FFTW f32 finite composition block changed")
    start, end = text.index(start_marker), text.index(end_marker)
    if start >= end or hashlib.sha256(_compact_zig_contract(text[start:end]).encode()).hexdigest() != FFTW_F32_BUILD_CONTRACT_SHA256:
        raise InventoryError("FFTW f32 generator/Core/binding/installation composition changed")
    # Enumerate the original source only after its complete block digest binds
    # the calls, comments and literal strings.
    calls = list(re.finditer(r'\bfftw_f32_directory\s*\.\s*path\s*\(\s*(b)\s*,\s*"([^"\n]+)"\s*\)', text[start:end]))
    if sorted(call.group(2) for call in calls) != ['abi_manifest.json', 'exports.zig', 'fftw3f_subset.h']:
        raise InventoryError("FFTW f32 generated LazyPath selection changed")
    uses = [(start + call.start(1), start + call.end(1)) for call in calls]
    link_rows = list(re.finditer(r"\bif\s*\(\s*fftw_f32_manifest\s*\)\s*\|manifest\|\s*\{", masked))
    if len(link_rows) != 1:
        raise InventoryError("FFTW f32 linker manifest forwarding changed")
    link, = link_rows
    link_end = _matching_brace(masked, masked.find('{', link.start(), link.end())) + 1
    if _compact_zig_contract(text[link.start():link_end]) != 'if(fftw_f32_manifest)|manifest|{abplas_lp64_shared.addArg("--fft-f32-manifest");abplas_lp64_shared.addFileArg(manifest);}':
        raise InventoryError("FFTW f32 linker must consume exactly the generated companion manifest")
    metadata_rows = list(re.finditer(r"\bconst\s+abplas_lp64_pc\s*=", masked))
    if len(metadata_rows) != 1:
        raise InventoryError("FFTW f32 package metadata declaration changed")
    metadata, = metadata_rows
    metadata_end = _zig_statement_end(masked, metadata.end(), len(masked)) + 1
    allowed = [(row.start(), option_end), (guard[0].start(), guard_end), (start, end), (metadata.start(), metadata_end)]
    for occurrence in re.finditer(r"\bfft_f32\b", masked):
        if not any(left <= occurrence.start() < right for left, right in allowed):
            raise InventoryError("FFTW f32 selector escapes finite reviewed composition")
    return {"build_contract_sha256": FFTW_F32_BUILD_CONTRACT_SHA256,
            "option_default": False, "requires": "fft-interface=fftw3",
            "cache_directory": "fftw3-f32", "receiver_uses": uses,
            "generated_module": "fftw_f32_exports_mod", "binding_owner": "fftw_binding_mod",
            "composed_module": "fftw_f32_composed_root", "Core_owner": "zynum_core_mod",
            "captured_base_before_assignment": "abplas_lp64_selected_root",
            "final_package_selection": {"fft-f32=false": "existing selected Module", "fft-f32=true": "fftw_f32_composed_root"}}


def _fftw_f32_receiver_uses(text: str) -> set[tuple[int, int]]:
    return {tuple(use) for use in _fftw_f32_build_contract(text)["receiver_uses"]}

FEAST_BUILD_CONTRACT_SHA256 = 'f8a2e9f79b8c5b1b66900522bee244a06cd621facffaa54a1067a902a4f9f213'

def _feast_build_contract(text: str) -> dict[str, Any]:
    """Bind the optional frontend to the same selected Core and package Module."""
    masked = _code_mask(text)
    enums = list(re.finditer(r"\bpub\s+const\s+FEASTInterfaceProfile\s*=\s*enum\s*\{[^}]*\};", masked))
    if len(enums) != 1 or _compact_zig_contract(text[enums[0].start():enums[0].end()]) != "pubconstFEASTInterfaceProfile=enum{none,feast4_lp64_abplas};":
        raise InventoryError("FEAST finite profile enum changed")
    options = list(re.finditer(r"\bconst\s+feast_interface\s*=", masked))
    if len(options) != 1:
        raise InventoryError("FEAST selector declaration missing or duplicated")
    option, = options
    option_end = _zig_statement_end(masked, option.end(), len(masked)) + 1
    if re.fullmatch(r'constfeast_interface=b\.option\(FEASTInterfaceProfile,"feast-interface","(?:\\.|[^"\\])*"\)orelse\.none;', _compact_zig_contract(text[option.start():option_end])) is None:
        raise InventoryError("FEAST selector default/type/name changed")
    guards = list(re.finditer(r"\bif\s*\(\s*feast_interface\s*!=\s*\.none\s+and\s*\(", masked))
    if len(guards) != 1:
        raise InventoryError("FEAST target guard missing or duplicated")
    guard, = guards
    guard_end = _matching_brace(masked, masked.find("{", guard.end())) + 1
    expected = 'if(feast_interface!=.noneand(target.result.os.tag!=.macosortarget.result.cpu.arch!=.aarch64)){std.log.err("feast-interface=feast4_lp64_abplas requires the unified Apple arm64 LP64 target",.{});b.invalid_user_input=true;}'
    if _compact_zig_contract(text[guard.start():guard_end]) != expected:
        raise InventoryError("FEAST supported target guard changed")
    markers = ("        var feast_manifest: ?std.Build.LazyPath = null;", "        var fftw_f32_manifest: ?std.Build.LazyPath = null;")
    if any(text.count(marker) != 1 for marker in markers):
        raise InventoryError("FEAST finite composition block missing or duplicated")
    start,end = (text.index(marker) for marker in markers)
    if start >= end or hashlib.sha256(_compact_zig_contract(text[start:end]).encode()).hexdigest() != FEAST_BUILD_CONTRACT_SHA256:
        raise InventoryError("FEAST generator/Core/binding/installation composition changed")
    borrows = list(re.finditer(r"\bconst\s+abplas_lp64_pre_feast_root\s*=", masked))
    if len(borrows) != 1:
        raise InventoryError("FEAST base Module borrow missing or duplicated")
    borrow, = borrows
    borrow_end = _zig_statement_end(masked, borrow.end(), len(masked)) + 1
    if _compact_zig_contract(text[borrow.start():borrow_end]) != "constabplas_lp64_pre_feast_root=abplas_lp64_selected_root;" or borrow_end > start:
        raise InventoryError("FEAST must capture the prior selected Module before composition")
    calls = list(re.finditer(r'\bfeast_directory\s*\.\s*path\s*\(\s*(b)\s*,\s*"([^"\n]+)"\s*\)', text[start:end]))
    if sorted(call.group(2) for call in calls) != sorted(["feast_exports.zig", "manifest.json", "feast_lp64.h", "FEASTConfig.cmake", "FEASTConfigVersion.cmake"]):
        raise InventoryError("FEAST generated LazyPath selection changed")
    links = list(re.finditer(r"\bif\s*\(\s*feast_manifest\s*\)\s*\|manifest\|\s*\{", masked))
    if len(links) != 1:
        raise InventoryError("FEAST linker manifest forwarding changed")
    link, = links
    link_end = _matching_brace(masked, masked.find("{", link.start(), link.end())) + 1
    if _compact_zig_contract(text[link.start():link_end]) != 'if(feast_manifest)|manifest|{abplas_lp64_shared.addArg("--feast-manifest");abplas_lp64_shared.addFileArg(manifest);}':
        raise InventoryError("FEAST linker must consume exactly its generated manifest")
    metadata = list(re.finditer(r"\bconst\s+abplas_lp64_pc\s*=", masked))
    if len(metadata) != 1:
        raise InventoryError("FEAST unified package metadata changed")
    metadata_end = _zig_statement_end(masked, metadata[0].end(), len(masked)) + 1
    allowed = [(option.start(),option_end),(guard.start(),guard_end),(start,end),(metadata[0].start(),metadata_end)]
    for occurrence in re.finditer(r"\bfeast_interface\b", masked):
        if not any(a <= occurrence.start() < b for a,b in allowed):
            raise InventoryError("FEAST selector escapes the finite composition")
    return {"build_contract_sha256":FEAST_BUILD_CONTRACT_SHA256,"option_default":"none","profile":"feast4_lp64_abplas","Core_owner":"zynum_core_mod","binding_owner":"feast_binding_mod","base_borrow":"abplas_lp64_pre_feast_root","composed_module":"feast_combined_mod","receiver_uses":[(start+c.start(1),start+c.end(1)) for c in calls]}

def _feast_receiver_uses(text: str) -> set[tuple[int, int]]:
    return {tuple(use) for use in _feast_build_contract(text)["receiver_uses"]}


def _provider_translation_receiver_uses(text: str) -> set[tuple[int, int]]:
    """The three reviewed reference calls, not arbitrary Builder forwarding."""
    calls = _calls(text, "translateProvider")
    if not calls:
        return set()
    expected = {
        "translateProvider(b,target,optimize,heteris_include)",
        "translateProvider(b,b.graph.host,optimize,heteris_include)",
        "translateProvider(b,runtime_lifecycle_target,test_optimize,heteris_include)",
    }
    observed = [_compact_zig_contract(call) for _, call in calls]
    if len(observed) != 3 or set(observed) != expected:
        raise InventoryError("unreviewed provider translation receiver use")
    uses = set()
    for position, call in calls:
        opening = text.find("(", position, position + len(call))
        match = re.match(r"\s*(b)\s*,", _code_mask(text)[opening + 1:])
        if match is None:
            raise InventoryError("provider translation must borrow the original Builder")
        uses.add((opening + 1 + match.start(1), opening + 1 + match.end(1)))
    return uses


def _zig_build_context(text: str, rel_path: str) -> ZigBuildContext:
    text = _reviewed_configure_projection(text)
    masked = _code_mask(text)
    matches = list(re.finditer(r"\b(?:pub\s+)?fn\s+build\s*\(", masked))
    if len(matches) != 1:
        raise InventoryError(
            f"{rel_path}: expected exactly one structurally recognizable build function"
        )
    signature = matches[0]
    open_paren = masked.find("(", signature.start(), signature.end())
    close_paren = _matching_paren(text, open_paren)
    open_brace = masked.find("{", close_paren)
    if open_brace < 0 or ";" in masked[close_paren:open_brace]:
        raise InventoryError(f"{rel_path}: build function body is unsupported")
    close_brace = _matching_brace(masked, open_brace)
    parameters = _split_top_level(text[open_paren + 1 : close_paren])
    build_parameters: list[str] = []
    for parameter in parameters:
        match = re.fullmatch(
            r"(?:comptime\s+)?([A-Za-z_][A-Za-z0-9_]*|_)\s*:\s*\*\s*(?:const\s+)?std\.Build",
            _code_mask(parameter).strip(),
        )
        if match is not None and match.group(1) != "_":
            build_parameters.append(match.group(1))
    if len(build_parameters) > 1:
        raise InventoryError(f"{rel_path}: build receiver parameter is ambiguous")

    body_start = open_brace + 1
    body_end = close_brace
    receiver = build_parameters[0] if build_parameters else None
    receivers = {receiver: body_start} if receiver is not None else {}
    declaration_names: set[tuple[int, int]] = set()
    safe_alias_sources: set[tuple[int, int]] = (
        _multiversion_factory_contract(text)
        if rel_path == "build.zig" and "buildKernelTiers" in masked else set()
    )
    if rel_path == "build.zig" and "install_checked_abi" in masked:
        safe_alias_sources.update(_checked_abi_receiver_uses(text))
    if rel_path == "build.zig" and re.search(r"\bfft_f32\b", masked):
        safe_alias_sources.update(_fftw_f32_receiver_uses(text))
    if rel_path == "build.zig" and re.search(r"\bfeast_interface\b", masked):
        safe_alias_sources.update(_feast_receiver_uses(text))
    if rel_path == "build.zig":
        safe_alias_sources.update(_provider_translation_receiver_uses(text))
    declaration_pattern = re.compile(
        r"\b(?P<kind>const|var)\s+(?P<name>[A-Za-z_][A-Za-z0-9_]*)"
        r"(?:\s*:[^=;\n]+)?\s*="
    )
    for declaration in declaration_pattern.finditer(masked, body_start, body_end):
        name = declaration.group("name")
        declaration_names.add(declaration.span("name"))
        statement_end = _zig_statement_end(masked, declaration.end(), body_end)
        rhs = masked[declaration.end() : statement_end].strip()
        if name in receivers:
            raise InventoryError(
                f"{rel_path}: Zig build receiver {name!r} is shadowed or rebound"
            )
        source_receiver = next(
            (candidate for candidate in receivers if rhs == candidate), None
        )
        if source_receiver is not None:
            if (
                declaration.group("kind") != "const"
                or _zig_brace_depth(masked, open_brace, declaration.start()) != 1
            ):
                raise InventoryError(
                    f"{rel_path}: scoped or mutable Zig build receiver aliases are unsupported"
                )
            rhs_prefix = masked[declaration.end() : statement_end]
            source_start = (
                declaration.end() + len(rhs_prefix) - len(rhs_prefix.lstrip())
            )
            safe_alias_sources.add((source_start, source_start + len(source_receiver)))
            receivers[name] = statement_end + 1
            continue

    for candidate in receivers:
        assignment_pattern = re.compile(
            rf"(?<![A-Za-z0-9_.]){re.escape(candidate)}\s*=(?!=)"
        )
        for assignment in assignment_pattern.finditer(masked, body_start, body_end):
            if any(
                start <= assignment.start() < end for start, end in declaration_names
            ):
                continue
            raise InventoryError(
                f"{rel_path}: Zig build receiver {candidate!r} is shadowed or rebound"
            )

    for candidate, available_at in receivers.items():
        use_pattern = re.compile(
            rf"(?<![A-Za-z0-9_]){re.escape(candidate)}(?![A-Za-z0-9_])"
        )
        for use in use_pattern.finditer(masked, body_start, body_end):
            if any(start <= use.start() < end for start, end in declaration_names):
                continue
            if use.span() in safe_alias_sources:
                continue
            prefix = masked[body_start : use.start()].rstrip()
            if prefix.endswith("."):
                continue
            if use.start() < available_at:
                raise InventoryError(
                    f"{rel_path}: Zig build receiver alias {candidate!r} is used before its declaration"
                )
            suffix = masked[use.end() :].lstrip()
            direct_member = re.match(r"\.\s*[A-Za-z_][A-Za-z0-9_]*", suffix)
            nested_function = any(
                re.search(r"\bfn\b", _code_mask(header))
                and not re.search(r"\bfn\s+build\b", _code_mask(header))
                for header in _enclosing_control_context(text, use.start())
            )
            if direct_member is not None and not nested_function:
                continue
            raise InventoryError(
                f"{rel_path}: Zig build receiver {candidate!r} escapes the analyzed build body"
            )

    build = ZigBuildContext(receiver, receivers, body_start, body_end)
    member_pattern = re.compile(
        rf"(?<![A-Za-z0-9_])(?P<receiver>[A-Za-z_][A-Za-z0-9_]*)\s*\.\s*"
        rf"(?P<method>{'|'.join(sorted(map(re.escape, ZIG_BUILD_RECEIVER_METHODS), key=len, reverse=True))})\s*\("
    )
    for call in member_pattern.finditer(masked, body_start, body_end):
        call_receiver = call.group("receiver")
        if call_receiver not in receivers:
            raise InventoryError(
                f"{rel_path}: build API call uses unsupported or ambiguous receiver {call_receiver!r}"
            )
        if call.start() < receivers[call_receiver]:
            raise InventoryError(
                f"{rel_path}: Zig build receiver alias {call_receiver!r} is used before its declaration"
            )
    if receiver is None and member_pattern.search(masked, body_start, body_end):
        raise InventoryError(f"{rel_path}: build receiver parameter is unsupported")
    return build


def _discover_option_surface_semantics(
    root: Path, context: DiscoveryContext | None = None
) -> dict[tuple[str, str], dict[str, str]]:
    active = _context_for(root, context)
    root = active.root
    result: dict[tuple[str, str], dict[str, str]] = {}
    for rel in active.build_roots:
        text = _reviewed_configure_projection(_frozen_regular_text(active, rel, "build root"))
        build = _zig_build_context(text, rel)
        option_calls = sorted(
            (
                occurrence
                for receiver in build.receivers
                for occurrence in _zig_member_calls(text, build, receiver, "option")
            ),
            key=lambda occurrence: occurrence[0],
        )
        for position, call in option_calls:
            body = call[call.find("(") + 1 : -1]
            arguments = _split_top_level(body)
            if len(arguments) < 3:
                continue
            name = json.loads(arguments[1])
            description = json.loads(arguments[2])
            semicolon = text.find(";", position + len(call))
            trailer = text[
                position + len(call) : semicolon
                if semicolon >= 0
                else position + len(call)
            ]
            default_match = re.search(r"\borelse\s+\.?(\w+)", trailer)
            default = default_match.group(1) if default_match else "unset"
            if rel == "build.zig" and name in {"checked-nm", "checked-readobj", "checked-gfortran"}:
                expected_default = {"checked-nm": "nm", "checked-readobj": "llvm-readobj", "checked-gfortran": "gfortran"}[name]
                if _compact_zig_contract(trailer) != "orelse" + json.dumps(expected_default):
                    raise InventoryError("checked ABI tool option default changed")
                default = expected_default
            if rel == "examples/zig/build.zig" and name == "dispatch":
                if _compact_zig_contract(trailer) != 'orelse"auto"':
                    raise InventoryError("example dispatch default must preserve explicit caller CPU intention")
                default = "auto"
            if rel == "build.zig" and name == "optimize":
                if _compact_zig_contract(trailer) != "orelseb.standardOptimizeOption(.{.preferred_optimize_mode=.fast})":
                    raise InventoryError("explicit optimize must preserve standard release fallback")
                default = "standard release selection"
            result[(rel, name)] = {
                "type": arguments[0],
                "default": default,
                "description": description,
            }
        standard_defaults: dict[str, tuple[str, str, str]] = {
            "target": (
                "target-query",
                "native requested target",
                "Select target triple",
            ),
            "cpu": (
                "cpu-model-and-features",
                "architecture baseline CPU selection" if rel == "build.zig" else "target default CPU selection",
                "Select CPU model and feature set",
            ),
            "ofmt": (
                "object-format",
                "target default object format",
                "Select output object format",
            ),
            "dynamic-linker": (
                "path",
                "target default dynamic linker",
                "Select dynamic linker path",
            ),
        }
        if rel == "build.zig":
            standard_defaults["release"] = (
                "bool",
                "false",
                "Request Zig standard release optimization resolution",
            )
        else:
            standard_defaults["optimize"] = (
                "std.lang.Optimize",
                "debug",
                "Select debug, safe, fast, or small optimization",
            )
        for name, (option_type, default, description) in standard_defaults.items():
            result[(rel, name)] = {
                "type": option_type,
                "default": default,
                "description": description,
            }
    raw = _frozen_regular_text(active, "build.zig", "build root")
    if re.search(r"\bpub\s+const\s+ExecutionProfile\s*=", _code_mask(raw)):
        _reviewed_configure_projection(raw)
        raw_mask = _code_mask(raw)
        option_spans = []
        for helper in ("configureIntegrated", "headerIncludePath"):
            match = re.search(r"\bfn\s+" + helper + r"\s*\(", raw_mask)
            assert match is not None
            opening = raw_mask.find("{", match.end())
            option_spans.append((opening + 1, _matching_brace(raw_mask, opening)))
        configure = re.search(r"\bpub\s+fn\s+configure\s*\(", raw_mask)
        assert configure is not None
        opening = raw_mask.find("{", configure.end())
        option_spans.append((opening + 1, raw_mask.index("const blas_interface", opening)))
        for position, call in _calls(raw, "b.option"):
            if not any(start <= position < end for start, end in option_spans):
                continue
            arguments = _split_top_level(call[call.find("(") + 1:-1])
            if len(arguments) != 3 or not arguments[1].startswith('"'):
                continue
            name, description = json.loads(arguments[1]), json.loads(arguments[2])
            if ("build.zig", name) in result:
                continue
            if name not in {row["name"] for row in INJECTION_OPTION_SURFACES}:
                continue
            semicolon = raw.find(";", position + len(call))
            trailer = raw[position + len(call):semicolon]
            match = re.search(r"\borelse\s+\.?(\w+)", trailer)
            default = match.group(1) if match else "unset"
            if name == "reference-compat":
                default = "selected profile == reference"
            elif name == "heteris-include":
                default = "explicit ZYNUM_HETERIS_INCLUDE fallback"
            result[("build.zig", name)] = {"type": arguments[0], "default": default, "description": description}
    return result



