def _operator_phase_agreement_build_contract(text: str) -> None:
    masked = _code_mask(text)
    declarations = list(re.finditer(r"\bconst\s+operator_phase_agreement\s*=", masked))
    if len(declarations) != 1:
        raise InventoryError("operator phase selector declaration missing or duplicated")
    start = declarations[0].start()
    end = _zig_statement_end(masked, declarations[0].end(), len(masked)) + 1
    declaration = _compact_zig_contract(text[start:end])
    expected = r'constoperator_phase_agreement=b\.option\(bool,"operator-phase-agreement","(?:\\.|[^"\\])*"\)orelsefalse;'
    if re.fullmatch(expected, declaration) is None:
        raise InventoryError("operator phase selector default/type/name changed")
    targets = list(re.finditer(r"\bvar\s+target_query\s*=", masked))
    if len(targets) != 1 or targets[0].start() <= end:
        raise InventoryError("operator phase early configuration guard changed")
    configuration = _compact_zig_contract(text[start:targets[0].start()])
    if hashlib.sha256(configuration.encode()).hexdigest() != OPERATOR_PHASE_CONFIGURATION_CONTRACT_SHA256:
        raise InventoryError("operator phase early configuration guard changed")
    metadata_rows = list(re.finditer(r"\bconst\s+abplas_lp64_pc\s*=", masked))
    if len(metadata_rows) != 1:
        raise InventoryError("operator phase package metadata declaration changed")
    row = metadata_rows[0]
    metadata_end = _zig_statement_end(masked, row.end(), len(masked)) + 1
    metadata = _compact_zig_contract(text[row.start():metadata_end])
    if hashlib.sha256(metadata.encode()).hexdigest() != OPERATOR_PHASE_METADATA_CONTRACT_SHA256:
        raise InventoryError("operator phase package metadata selection changed")
    operator_start = text.find("        var abplas_lp64_selected_root = abplas_lp64_root;")
    operator_end = text.find("        abplas_lp64_static.bundle_compiler_rt = true;")
    admitted_spans = ((start, targets[0].start()), (operator_start, operator_end), (row.start(), metadata_end))
    for occurrence in re.finditer(r"\boperator_phase_agreement\b", masked):
        if not any(begin <= occurrence.start() < end for begin, end in admitted_spans):
            raise InventoryError("operator phase selector escapes reviewed configuration")


