def _potri_composition_build_contract(text: str) -> None:
    # Only these three borrowed Module choices are admitted. They retain the
    # existing Core; an alias is not a new Module or a new state owner.
    start = "        // Both export modules reuse the same exact Core and interface binding."
    end = "        // One named FFT binding Module is shared by both optional frontends."
    if text.count(start) != 1 or text.count(end) != 1:
        raise InventoryError("POTRI unified LAPACKE composition span changed")
    block = text[text.index(start):text.index(end)]
    if hashlib.sha256(_compact_zig_contract(block).encode()).hexdigest() != POTRI_UNIFIED_LAPACKE_BUILD_CONTRACT_SHA256:
        raise InventoryError("POTRI unified LAPACKE owner/binding selection changed")


