def _contour_build_contract(text: str) -> dict[str, Any]:
    """Review the optional forwarding/test blocks and the existing borrowed owner."""
    masked = _code_mask(text)
    enums = list(re.finditer(r"\bpub\s+const\s+ContourInterfaceProfile\s*=", masked))
    selectors = list(re.finditer(r"\bconst\s+contour_interface\s*=", masked))
    targets = list(re.finditer(r"\bvar\s+target_query\s*=", masked))
    if len(enums) != 1 or len(selectors) != 1 or len(targets) != 1:
        raise InventoryError("Contour selector declaration missing or duplicated")
    enum = enums[0]
    enum_end = _zig_statement_end(masked, enum.end(), len(masked)) + 1
    if _compact_zig_contract(text[enum.start():enum_end]) != "pubconstContourInterfaceProfile=enum{none,zynum_v1};":
        raise InventoryError("Contour selector enum changed")
    row = selectors[0]
    selector_end = _zig_statement_end(masked, row.end(), len(masked)) + 1
    selector = _compact_zig_contract(text[row.start():selector_end])
    if re.fullmatch(r'constcontour_interface=b\.option\(ContourInterfaceProfile,"contour-interface","(?:\\.|[^"\\])*"\)orelse\.none;', selector) is None:
        raise InventoryError("Contour selector type/default/name changed")
    markers = {
        "target": ('    if (contour_interface != .none and (target.result.os.tag', '    if (feast_interface != .none and (target.result.os.tag'),
        "package": ('        var abplas_lp64_selected_root = abplas_lp64_root;', '        abplas_lp64_static.bundle_compiler_rt = true;'),
        "test_wire": ('    const contour_test_generate =', '    const general_operator_test_mod ='),
        "test_profile": ('    const contour_profile_tests =', '    const checked_cholesky_tests ='),
    }
    spans = {"configuration": (row.start(), targets[0].start())}
    for key, (start, end) in markers.items():
        if text.count(start) != 1 or text.count(end) != 1:
            raise InventoryError("Contour reviewed span missing or duplicated: " + key)
        begin = text.index(start)
        stop = text.index(end, begin)
        spans[key] = (begin, stop)
    for key, (start, end) in spans.items():
        digest = hashlib.sha256(_compact_zig_contract(text[start:end]).encode()).hexdigest()
        if digest != CONTOUR_BUILD_CONTRACT_SHA256.get(key):
            raise InventoryError("Contour build/owner contract changed: " + key)
    metadata_rows = list(re.finditer(r"\bconst\s+abplas_lp64_pc\s*=", masked))
    if len(metadata_rows) != 1:
        raise InventoryError("Contour package metadata declaration changed")
    metadata = metadata_rows[0]
    metadata_end = _zig_statement_end(masked, metadata.end(), len(masked)) + 1
    admitted = [spans[key] for key in ("configuration", "target", "package")] + [(metadata.start(), metadata_end)]
    for occurrence in re.finditer(r"\bcontour_interface\b", masked):
        if not any(start <= occurrence.start() < end for start, end in admitted):
            raise InventoryError("Contour selector escapes its reviewed optional scope")
    return {"profile": "zynum-v1", "default": "none", "spans": dict(CONTOUR_BUILD_CONTRACT_SHA256),
            "operator_owner_borrow": "operator_binding_owner = operator_binding_mod", "new_runtime_owner": False}

def _numerics_resources_graph_facts(text: str) -> dict[str, Any]:
    """Extract only the reviewed owners, their declarations and exact edges.

    The compact digest below binds roots, inline imports, target/host identity,
    inherited optimize, declaration scopes, and the canonical attachment loop.
    No guessed aliases or execution observations are manufactured here.
    """
    text = _reviewed_configure_projection(text)
    fftw_f32_contract = _fftw_f32_build_contract(text)
    fftw_f32_contract.pop("receiver_uses")
    feast_contract = _feast_build_contract(text)
    feast_contract.pop("receiver_uses")
    _operator_phase_agreement_build_contract(text)
    _potri_composition_build_contract(text)
    _contour_build_contract(text)
    # These public selectors share existing owners and default to the existing
    # package. Reject shadow declarations, renamed/type-changed controls and
    # default-on substitutions before interpreting conditional source paths.
    selector_mask = _code_mask(text)
    blas_enums = list(re.finditer(r"\bpub\s+const\s+BLASInterfaceProfile\s*=", selector_mask))
    blas_selectors = list(re.finditer(r"\bconst\s+blas_interface\s*=", selector_mask))
    if len(blas_enums) != 1 or len(blas_selectors) != 1:
        raise InventoryError("LP64 BLAS selector declaration missing or duplicated")
    enum_start = blas_enums[0].start()
    enum_end = _zig_statement_end(selector_mask, blas_enums[0].end(), len(selector_mask)) + 1
    selector_start = blas_selectors[0].start()
    selector_end = _zig_statement_end(selector_mask, blas_selectors[0].end(), len(selector_mask)) + 1
    if _compact_zig_contract(text[enum_start:enum_end]) != "pubconstBLASInterfaceProfile=enum{none,lp64};":
        raise InventoryError("LP64 BLAS selector enum changed")
    blas_selector = _compact_zig_contract(text[selector_start:selector_end])
    if re.fullmatch(r'constblas_interface=b\.option\(BLASInterfaceProfile,"blas-interface","(?:\\.|[^"\\])*"\)orelse\.none;', blas_selector) is None:
        raise InventoryError("LP64 BLAS selector default/type/name changed")
    for symbol, flag in (("lapacke_qr", "lapacke-qr"),
                         ("lapacke_complex_gelsd", "lapacke-complex-gelsd"),
                         ("lapacke_svd", "lapacke-svd"),
                         ("lapacke_posv", "lapacke-posv"),
                         ("lapacke_trtrs", "lapacke-trtrs"),
                         ("lapacke_trtri", "lapacke-trtri"),
                         ("lapacke_getri", "lapacke-getri"),
                         ("lapacke_potri", "lapacke-potri"),
                         ("lapacke_syev", "lapacke-syev"),
                         ("lapacke_sygv", "lapacke-sygv"),
                         ("lapacke_controls", "lapacke-controls"),
                         ("lapacke_evd", "lapacke-evd"),
                         ("lapacke_gvd", "lapacke-gvd"),
                         ("lapacke_gels", "lapacke-gels"),
                         ("lapacke_gelss", "lapacke-gelss"),
                         ("fft_f32", "fft-f32")):
        declarations = list(re.finditer(rf"\bconst\s+{symbol}\s*=", selector_mask))
        if len(declarations) != 1:
            raise InventoryError("LP64 optional selector declaration changed: " + symbol)
        start = declarations[0].start()
        end = _zig_statement_end(selector_mask, declarations[0].end(), len(selector_mask)) + 1
        declaration = _compact_zig_contract(text[start:end])
        expected = rf'const{symbol}=b\.option\(bool,"{flag}","(?:\\.|[^"\\])*"\)orelsefalse;'
        if re.fullmatch(expected, declaration) is None:
            raise InventoryError("LP64 optional selector default/type/name changed: " + symbol)
    selection = []
    for symbol in ('lapacke_lp64_base_set', 'lapacke_lp64_before_trtrs_set', 'lapacke_lp64_before_trtri_set', 'lapacke_lp64_before_getri_set', 'lapacke_lp64_set', 'lapacke_ilp64_before_trtrs_set', 'lapacke_ilp64_before_trtri_set', 'lapacke_ilp64_before_getri_set', 'lapacke_ilp64_set'):
        declarations = list(re.finditer(rf"\bconst\s+{symbol}\s*=", selector_mask))
        if len(declarations) != 1:
            raise InventoryError("finite POSV selection declaration changed: " + symbol)
        start = declarations[0].start()
        end = _zig_statement_end(selector_mask, declarations[0].end(), len(selector_mask)) + 1
        selection.append(_compact_zig_contract(text[start:end]))
    if hashlib.sha256("".join(selection).encode()).hexdigest() != POSV_SELECTION_CONTRACT_SHA256:
        raise InventoryError("finite POSV selection contract changed")
    finite_start = "    // Finite LAPACKE packages share the configured numerical owner."
    finite_end = "    // One interface-owned Sparse shell family per existing implementation owner."
    if text.count(finite_start) != 1 or text.count(finite_end) != 1:
        raise InventoryError("finite LAPACKE install block missing or duplicated")
    finite_block = text[text.index(finite_start):text.index(finite_end)]
    if hashlib.sha256(_compact_zig_contract(finite_block).encode()).hexdigest() != FINITE_LAPACKE_BUILD_CONTRACT_SHA256:
        raise InventoryError("finite LAPACKE installation/owner/default-handler contract drifted")
    sparse_start = "    // Finite Sparse packages share the configured numerical owner."
    sparse_end = "    for (kernel_libraries) |library| {"
    if text.count(sparse_start) != 1 or text.count(sparse_end) != 1:
        raise InventoryError("finite Sparse install block missing or duplicated")
    sparse_block = text[text.index(sparse_start):text.index(sparse_end)]
    if hashlib.sha256(_compact_zig_contract(sparse_block).encode()).hexdigest() != FINITE_SPARSE_BUILD_CONTRACT_SHA256:
        raise InventoryError("finite Sparse installation/shared-owner contract drifted")
    operator_start = "        var abplas_lp64_selected_root = abplas_lp64_root;"
    operator_end = "        abplas_lp64_static.bundle_compiler_rt = true;"
    if text.count(operator_start) != 1 or text.count(operator_end) != 1:
        raise InventoryError("operator package build block missing or duplicated")
    operator_span = (text.index(operator_start), text.index(operator_end))
    if hashlib.sha256(text[operator_span[0]:operator_span[1]].encode()).hexdigest() != OPERATOR_PACKAGE_BUILD_CONTRACT_SHA256:
        raise InventoryError("operator generated module and shared-owner build contract drifted")
    text = _reviewed_configure_projection(text)
    # Also reject an otherwise disconnected duplicate binding/configuration root.
    # The existing exact declaration/edge digest binds the two admitted owners.
    paths = [_first_string(call) for _, call in _calls(text, "b.path")]
    if "src/numerics/execution/default.zig" in paths:
        raise InventoryError("unreviewed same-source owner: direct legacy default module")
    for path, count in INTERFACE_BINDING_ROOT_COUNTS.items():
        if paths.count(path) != count:
            raise InventoryError("interface binding/configuration root ownership changed: " + path)
    masked = _code_mask(text)
    roots = [row[1].rsplit(":", 1)[1] for row in REQUIRED_TEST_INVENTORY_FACTORY_CASES]
    pending = set(roots) | set(SHARED_FACADE_OWNERS) | {owner for owner in (*SHARED_ADAPTER_CORE_OWNERS, *SHARED_ADAPTER_IMPORTS) if "." not in owner} | {
        owner for owner in NUMERICS_RESOURCES_OWNERS if "." not in owner
    } | {"provider_c", "runtime_lifecycle_provider_c", "numerics_resources_mod", "host_numerics_resources_mod",
         "resources_host_matches_target", "runtime_lifecycle_resources_mod", "combined_interfaces_lib", "build_combined_interfaces_step", "dynamic_tests", "generate_kernel_coverage_tool",
         "execution_mod", "execution_test_mod", "zynum_build_options_mod", "abplas_lp64_pre_blas_root", "abplas_lp64_pre_feast_root", "abplas_lp64_pre_contour_root",
         "runtime_lifecycle_execution_mod", "runtime_lifecycle_options_mod",
         "task_runtime_host_test_library", "runtime_lifecycle_probe", "run_structured_object_tests",
         "run_execution_contract_tests", "execution_contract_test_step", "checked_cholesky_tests", "lapacke_posv_tests"}
    declarations: dict[str, list[dict[str, Any]]] = {}
    declaration_text: dict[str, str] = {}
    spans: list[tuple[int, int]] = [operator_span]
    while pending:
        name = min(pending)
        pending.remove(name)
        if name in declarations:
            continue
        matches = list(re.finditer(rf"\bconst\s+{re.escape(name)}\s*=", masked))
        expected_count = 2 if name == "structured_object_tests" else 1
        if len(matches) != expected_count:
            raise InventoryError(f"numerics resources owner declaration changed: {name}")
        declarations[name] = []
        for match in matches:
            start = match.start()
            end = _zig_statement_end(masked, match.end(), len(masked)) + 1
            block = text[start:end]
            spans.append((start, end))
            declarations[name].append({
                "source": _compact_zig_contract(block),
                "context": [_compact_zig_contract(x) for x in _enclosing_control_context(text, start)],
            })
            declaration_text.setdefault(name, block)
            for module in re.findall(r"\.(?:root_module|module)\s*=\s*([A-Za-z_][A-Za-z0-9_]*)", _code_mask(block)):
                if module != "b":
                    pending.add(module)
    provider_c_edges = []
    for position, call in _calls(text, ".addImport"):
        if _first_string(call) != "heteris-provider-c":
            continue
        receiver = re.search(r"[A-Za-z_][A-Za-z0-9_.]*\s*$", masked[:position])
        if receiver is None:
            raise InventoryError("provider C import receiver changed")
        start, end = receiver.start(), position + len(call)
        # A same-target resource module must not receive a freshly translated
        # host binding. Bind this reviewed single-statement condition as part
        # of the edge, not as an untracked escape of the target identity flag.
        conditional = re.search(r"\bif\s*\(\s*!\s*resources_host_matches_target\s*\)\s*$", masked[:start])
        if conditional is not None:
            start = conditional.start()
        spans.append((start, end))
        provider_c_edges.append({"source": _compact_zig_contract(text[start:end]),
            "context": [_compact_zig_contract(x) for x in _enclosing_control_context(text, start)]})
    edges = []
    for owner in NUMERICS_RESOURCES_OWNERS:
        matches = list(re.finditer(rf"(?<![A-Za-z0-9_.]){re.escape(owner)}\s*\.\s*addImport\s*\(", masked))
        relevant = []
        for match in matches:
            end = _matching_paren(text, masked.find("(", match.start(), match.end())) + 1
            call = text[match.start():end]
            if _first_string(call) == NUMERICS_RESOURCES_ALIAS:
                relevant.append((match.start(), end, call))
        if len(relevant) != 1:
            raise InventoryError(f"numerics resources import edge missing or duplicated: {owner}")
        start, end, call = relevant[0]
        provider = ("host_numerics_resources_mod" if owner == "kernel_coverage_mod" else
                    "runtime_lifecycle_resources_mod" if owner == "runtime_lifecycle_execution_mod" else
                    "numerics_resources_mod")
        expected = f'{owner}.addImport("{NUMERICS_RESOURCES_ALIAS}",{provider})'
        if _compact_zig_contract(call) != expected:
            raise InventoryError(f"numerics resources provider changed: {owner}")
        spans.append((start, end))
        edges.append({"owner": owner, "provider": provider,
                      "context": [_compact_zig_contract(x) for x in _enclosing_control_context(text, start)]})
    execution_edges = []
    for owner, provider in EXECUTION_IMPORT_OWNERS.items():
        matches = []
        for match in re.finditer(rf"(?<![A-Za-z0-9_.]){re.escape(owner)}\s*\.\s*addImport\s*\(", masked):
            end = _matching_paren(text, masked.find("(", match.start(), match.end())) + 1
            call = text[match.start():end]
            if _first_string(call) == EXECUTION_ALIAS:
                matches.append((match.start(), end, call))
        if len(matches) != 1:
            raise InventoryError(f"shared execution import edge missing or duplicated: {owner}")
        start, end, call = matches[0]
        if _compact_zig_contract(call) != f'{owner}.addImport("{EXECUTION_ALIAS}",{provider})':
            raise InventoryError(f"shared execution provider changed: {owner}")
        spans.append((start, end))
        execution_edges.append({"owner": owner, "provider": provider,
                                "context": [_compact_zig_contract(x) for x in _enclosing_control_context(text, start)]})
    if sum(_first_string(call) == EXECUTION_ALIAS for _, call in _calls(text, ".addImport")) != len(EXECUTION_IMPORT_OWNERS):
        raise InventoryError("shared execution has an unreviewed import owner")
    option_edges = []
    for position, call in _calls(text, ".addImport"):
        if _first_string(call) != "zynum-build-options":
            continue
        receiver = re.search(r"[A-Za-z_][A-Za-z0-9_.]*\s*$", masked[:position])
        if receiver is None:
            raise InventoryError("shared execution options receiver changed")
        start, end = receiver.start(), position + len(call)
        spans.append((start, end))
        option_edges.append({"source": _compact_zig_contract(text[start:end]),
                             "context": [_compact_zig_contract(x) for x in _enclosing_control_context(text, start)]})
    # Facades have one explicitly resolved core, never their own resources/options/objects.
    core_edges = []
    for owner, provider in {**SHARED_FACADE_OWNERS, **SHARED_ADAPTER_CORE_OWNERS}.items():
        matches = list(re.finditer(rf"(?<![A-Za-z0-9_.]){re.escape(owner)}\s*\.\s*addImport\s*\(", masked))
        if owner in SHARED_ADAPTER_CORE_OWNERS:
            matches = [match for match in matches if _first_string(text[match.start():
                _matching_paren(text, masked.find("(", match.start(), match.end())) + 1]) == "zynum-core"]
        if len(matches) != 1:
            raise InventoryError(f"numerics resources shared facade import changed: {owner}")
        match, = matches
        end = _matching_paren(text, masked.find("(", match.start(), match.end())) + 1
        call = text[match.start():end]
        if _compact_zig_contract(call) != f'{owner}.addImport("zynum-core",{provider})':
            raise InventoryError(f"numerics resources shared core provider changed: {owner}")
        spans.append((match.start(), end))
