def _injection_observation_templates() -> dict[str, dict[str, Any]]:
    """Source-only factories from the finite, fully bound original-Core helpers."""
    rows: dict[str, dict[str, Any]] = {}
    prefix = "build.zig:configureIntegrated:"
    condition = "execution-profile=integrated_native"
    runtime = condition + "; explicit absolute heteris-runtime-archive supplied; named test step reached"
    for name in ("optimize-override", "optimize", "target", "test-optimize", "dispatch",
                 "thread-limit", "default-owner", "compatibility-frontends", "host-tool-smoke",
                 "shared", "standalone", "native-identity-tests", "poison-reference", "heteris-runtime-archive"):
        rows["option:" + prefix + name] = {"owner": "build-composition"}
    for name in ("execution-profile", "reference-compat"):
        rows["option:build.zig:configure:" + name] = {"owner": "build-composition"}
    rows["option:integrations/heteris/build.zig:build:optimize-override"] = {"owner": "build-composition"}
    for identifier in ("option:build.zig:build:poison-reference",
                       "option:build.zig:headerIncludePath:heteris-include"):
        rows[identifier] = {"owner": "build-composition"}
    def compile_row(source: str, kind: str, name: str, when: str) -> dict[str, Any]:
        return {"owner": "test-infrastructure" if kind in {"test", "executable"} else "build-composition",
                "artifact_kind": kind, "output_name": name, "root_source": [source],
                "linkage": "not-applicable", "compile_for": "requested-target",
                "execute_on": "requested-target" if kind in {"test", "executable"} else "not-executable",
                "optimize_source": "optimize", "condition": when,
                "produced_outputs": [name, name + ".exe"] if kind in {"test", "executable"} else [name],
                "install_destinations": [], "native_inventory_evidence": False}
    rows["compile:" + prefix + "math_tests"] = compile_row(
        "src/native_provider_math_test.zig", "test", "zynum-native-provider-math-tests", runtime)
    rows["compile:" + prefix + "c_tests"] = compile_row(
        "integrations/heteris/tests/native_runtime.c", "executable", "zynum-native-runtime-c-tests", runtime)
    for symbol, producer in (("anonymous", "math_tests"), ("anonymous-2", "c_tests")):
        rows["launch:" + prefix + symbol] = {
            "owner": "test-infrastructure", "detail_status": "process-lifecycle-out-of-scope",
            "cwd_shape": "repository-root", "command_shape": "run-artifact",
            "source_artifact": "compile:" + prefix + producer, "compile_for": "requested-target",
            "execute_on": "requested-target", "argv_shape": [], "launch_class": "validation",
            "condition": runtime, "native_inventory_evidence": False}
    for name, description, dependency, when in (
        ("native-graph", "Validate exact original module identities without compiling mathematical functions",
         "install:" + prefix + "share/zynum/native-graph.json", condition),
        ("test-native-provider-math", "Run original-Core explicit math tests against an explicitly supplied prebuilt Runtime",
         "launch:" + prefix + "anonymous", runtime),
        ("test-native-runtime-c", "Run the native C API with an explicitly supplied formal Runtime",
         "launch:" + prefix + "anonymous-2", runtime)):
        rows["step:" + prefix + name] = {
            "owner": "test-infrastructure", "description": description,
            "direct_dependencies": [{"id": dependency, "condition": when}],
            "aggregate_test_membership": "not-member", "aggregate_condition": "not-applicable",
            "intentional_orphan": False, "orphan_reason": "explicit integrated native entry point",
            "step_role": "correctness", "native_inventory_evidence": False}
    rows["link:" + prefix + "c_module<-library"] = {
        "owner": "test-infrastructure", "consumer": "c_module", "provider": "library", "condition": runtime}
    rows["install:" + prefix + "share/zynum/native-graph.json"] = {
        "owner": "build-composition", "producer": "checked-in build declaration",
        "source": "generated native-graph.json", "destination": ["zig-out/share/zynum/native-graph.json"],
        "condition": condition}
    platform = "build.zig:addPlatformLibrary:"
    old = _heteris_adapter_observation_templates()
    bridge = "integrations/heteris/build.zig:build:"
    for symbol in ("library", "provider", "tests", "translated"):
        row = copy.deepcopy(old["compile:" + bridge + symbol])
        row["condition"] = condition + ("; standalone=true" if symbol == "provider" else
                                      "; test-platform reached" if symbol == "tests" else "")
        row["native_inventory_evidence"] = False
        if symbol == "library":
            row["root_source"] = ["integrations/heteris/src/native_exports.zig"]
        rows["compile:" + platform + symbol] = row
    for symbol, producer, when in (("installed", "library", condition), ("provider", "provider", condition + "; standalone=true")):
        rows["install:" + platform + symbol] = {
            "owner": "build-composition", "producer": "compile:" + platform + producer,
            "source": "emitted artifact",
            "destination": rows["compile:" + platform + producer]["install_destinations"], "condition": when}
    for key, sources, destinations, when in (
        ("integrations/heteris/include/{s}", ["integrations/heteris/include/zynum.h", "integrations/heteris/include/zynum_spectral.h"],
         ["zig-out/include/zynum.h", "zig-out/include/zynum_spectral.h"], condition),
        ("include/zynum_native.h", ["include/zynum_native.h"], ["zig-out/include/zynum_native.h"], condition),
        ("integrations/heteris/include/zynum_standalone.h", ["integrations/heteris/include/zynum_standalone.h"],
         ["zig-out/include/zynum_standalone.h"], condition + "; standalone=true"),
        ("sdk-headers", ["explicit heteris-include/heteris.h", "explicit heteris-include/heteris_runtime_provider.h"],
         ["zig-out/include/heteris.h", "zig-out/include/heteris_runtime_provider.h"], condition)):
        rows["install:" + platform + key] = {
            "owner": "build-composition", "producer": "external Heteris Data SDK file" if key == "sdk-headers" else "repository file",
            "source": sources, "destination": destinations, "condition": when}
    rows["launch:" + platform + "run"] = {
        "owner": "test-infrastructure", "detail_status": "process-lifecycle-out-of-scope",
        "cwd_shape": "repository-root", "command_shape": "run-artifact",
        "source_artifact": "compile:" + platform + "tests", "compile_for": "requested-target",
        "execute_on": "requested-target", "argv_shape": [], "launch_class": "validation",
        "condition": condition + "; test-platform reached", "native_inventory_evidence": False}
    for name, description, deps in (
        ("platform", "Build the single main libzynum with the configured original Core",
         [{"id": "install:" + platform + key, "condition": condition + ("; standalone=true" if key in {"provider", "integrations/heteris/include/zynum_standalone.h"} else "")}
          for key in ("installed", "provider", "sdk-headers", "integrations/heteris/include/{s}", "include/zynum_native.h", "integrations/heteris/include/zynum_standalone.h")]),
        ("test-platform", "Run existing adapter tests in the root-owned graph",
         [{"id": "launch:" + platform + "run", "condition": condition}])):
        rows["step:" + platform + name] = {
            "owner": "build-composition", "description": description, "direct_dependencies": deps,
            "aggregate_test_membership": "not-member", "aggregate_condition": "not-applicable",
            "intentional_orphan": False, "orphan_reason": "explicit original-Core native package entry point",
            "step_role": "packaging" if name == "platform" else "correctness"}
    rows["compile:build.zig:translateProvider:translated"] = {
        "owner": "build-composition", "artifact_kind": "translated-source", "output_name": "zynum_native.zig",
        "root_source": ["include/zynum_native.h"], "linkage": "not-applicable",
        "compile_for": "caller-target",
        "target_parameter": "target",
        "target_variants": ["requested target", "build host", "fixed aarch64-macos lifecycle target"],
        "execute_on": "not-executable", "optimize_source": "caller optimize",
        "condition": "either mutually exclusive execution profile; explicit SDK; target-compatible provider C module reused",
        "produced_outputs": ["zynum_native.zig"], "install_destinations": [],
        "external_include_dependencies": ["heteris.h", "heteris_runtime_provider.h"],
        "native_inventory_evidence": False}
    # The bridge has no factories: standard dependency forwards to these exact
    # root-owned steps. Keep the old lifecycle IDs, with actual delegated edges.
    for name, target in (("install", "platform"), ("test", "test-platform")):
        rows["step:" + bridge + name] = {
            **copy.deepcopy(old["step:" + bridge + name]),
            "description": "Install declared artifacts" if name == "install" else "Run the existing adapter tests in the original root graph",
            "direct_dependencies": [{"id": "step:" + platform + target,
                                     "condition": "standard original_zynum dependency; execution-profile=integrated_native"}],
            "orphan_reason": "standard local dependency delegates to the single original Core graph"}
    return rows



def _injection_option_surfaces() -> list[dict[str, Any]]:
    rows = []
    for name, kind, default, description, observation in (
        ("blas-interface", "BLASInterfaceProfile", "none", "Optional existing LP64 CBLAS and Fortran BLAS frontend for the unified package", "build:blas-interface"),
        ("fft-interface", "FFTInterfaceProfile", "none", "Optional FFT frontend for the unified LP64 package: none or FFTW3 f64 ABPLaS profile", "build:fft-interface"),
        ("operator-interface", "OperatorInterfaceProfile", "none", 'Optional generated synchronous callback frontend for the unified LP64 package', "build:operator-interface"),
        ("execution-profile", "ExecutionProfile", "reference", "reference compatibility or explicit integrated_native", "configure:execution-profile"),
        ("reference-compat", "bool", "selected profile == reference", "Enable reference-only default owner and compatibility services", "configure:reference-compat"),
        ("heteris-include", "[]const u8", "explicit ZYNUM_HETERIS_INCLUDE fallback", "Explicit absolute header-only Heteris Data SDK include directory", "headerIncludePath:heteris-include"),
        ("shared", "bool", "false", "Build the one main library as shared (default static)", "configureIntegrated:shared"),
        ("standalone", "bool", "false", "Emit separate explicit standalone adapter provider", "configureIntegrated:standalone"),
        ("native-identity-tests", "bool", "false", "Test-only immutable loaded-image identity queries", "configureIntegrated:native-identity-tests"),
        ("poison-reference", "bool", "false", "Test-only poison for actual legacy reference imports", "build:poison-reference"),
        ("heteris-runtime-archive", "[]const u8", "unset", "Explicit absolute prebuilt formal Runtime archive; only enables requested provider test targets", "configureIntegrated:heteris-runtime-archive"),
        ("default-owner", "bool", "false", "Forbidden integrated default owner", "configureIntegrated:default-owner"),
    ):
        rows.append({
            "id": "option-surface:build.zig:" + name, "build_root": "build.zig", "name": name,
            "option_kind": "project", "type": kind, "default": default, "description": description,
            "consumers": ["reviewed original-Core configure/profile helpers"],
            "role": "explicit profile or native test configuration",
            "conflict": ("CLI and explicit environment paths must normalize to the same absolute SDK" if name == "heteris-include"
                         else "reference-compat must equal (execution-profile == reference)" if name in {"execution-profile", "reference-compat"}
                         else "integrated_native forbids true" if name == "default-owner" else "none"),
            "precedence": ("explicit CLI; matching explicit SDK environment remains required for nested reference builders" if name == "heteris-include"
                           else "explicit command-line value; the recorded default otherwise"),
            "source_observation": "option:build.zig:" + observation,
        })
    return rows


